def rxe_raw(name):
    row=RXE_CAPTURE['raw'][name];raw=base64.b64decode(row['b64'],validate=True)
    if hashlib.sha256(raw).hexdigest()!=row['sha256']:raise ValueError('CAPTURE_HASH_DRIFT')
    return raw.decode()

def rxe_tree(root):
    base=root/'rxe0/ports/1'
    for name in ('gids','gid_attrs/types','gid_attrs/ndevs'):(base/name).mkdir(parents=True)
    for line in rxe_raw('rxe0-port1-gid-type-ndev.txt').splitlines():
        index,gid,tail=line.split(' ',2);kind,netdev=tail.rsplit(' ',1)
        (base/'gids'/index).write_text(gid)
        if gid!='0000:0000:0000:0000:0000:0000:0000:0000':
            (base/'gid_attrs/types'/index).write_text(kind);(base/'gid_attrs/ndevs'/index).write_text(netdev)
    return base

